// Synthetic, hand-labeled. Labels hold only what the writer states outright,
// plus the topic of any bill named, since that is how the app files it.
// "test" (the n set) is held out: write a new held-out set before tuning on it.
// "second" (the s set) is what rules alone cannot read: mail they set aside that a person wrote, and bills named without a number or title.
// "fresh" (the f set) was written on 2026-11-11 before the rules learned from the n and s misses, to score those fixes on unseen wording.
export type EvalCase = {
  id: string;
  split: "dev" | "test" | "second" | "fresh";
  scenario: string;
  subject: string;
  body: string;
  from?: string;
  headers?: Record<string, string>;
  sentAt?: string;
  gold: {
    types: string[];
    issues: string[]; // leaf taxonomy keys
    bills: { ref: string; resolution: "resolved" | "ambiguous" | "unmatched" | "out_of_jurisdiction"; bill?: string }[];
    positions: { target: string; position: "support" | "oppose" | "mixed" | "neutral" | "unclear" }[];
    actions: string[];
  };
};

